-- Base tables as created 2026-11-05 (used only to build an empty fixture database; production already has them).
CREATE TABLE IF NOT EXISTS eventos (id bigserial primary key, ts timestamptz not null default now(), ev text not null, vid text, sid text, page text, lang text, path text, utm_source text, utm_medium text, utm_campaign text, utm_content text, utm_term text, ref text, landing text, extra jsonb);
CREATE TABLE IF NOT EXISTS roda (id bigserial primary key, ts timestamptz not null default now(), vid text, sid text, lang text, q1 text,q2 text,q3 text,q4 text,q5 text,q6 text,q7 text,q8 text, prioridade text, ordem text, g text, r text, utm_source text, utm_medium text, utm_campaign text, utm_content text, utm_term text, ref text);
CREATE TABLE IF NOT EXISTS compras (id bigserial primary key, ts timestamptz not null default now(), pedido text, status text, valor numeric, produto text, parcelas int, vid text, utm_source text, utm_medium text, utm_campaign text, utm_content text, utm_term text, src text, sck text, xcod text, raw jsonb);
